// Extract message data
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

// Check if it's a valid message
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, null, null, null, answerCallback];
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Only handle SMS-specific commands
if (command !== '/sms' && command !== '/sms_status' && command !== '/sms_log') {
    return [null, null, null, null, answerCallback];
}

const requestId = Date.now().toString(36) + Math.random().toString(36).substr(2);
node.warn(`[${requestId}] SMS Command: ${command} from chat ${chatId}`);

// Prepare message
msg.requestId = requestId;
msg.chatId = chatId;
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// Initialize array with null positions for ALL 5 outputs
let output = [null, null, null, null, null];

// Route to appropriate handler
if (command === '/sms') {
    output[0] = msg;
    output[4] = answerCallback;
} else if (command === '/sms_status') {
    output[1] = msg;
    output[4] = answerCallback;
} else if (command === '/sms_log') {
    output[2] = msg;
    output[4] = answerCallback;
} else {
    output[4] = answerCallback;
}

return output;

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

// Parse: /sms <phone> <message>
const args = msg.telegram.args;

if (args.length < 2) {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: `❌ Invalid format\n\nUsage: /sms <phone> <message>\n\nExample:\n/sms +1234567890 Hello from Telegram!`
    };
    msg.topic = 'send';
    return msg;
}

const phone = args[0];
const message = args.slice(1).join(' ');

// Validate phone number (basic check)
if (!phone.startsWith('+') && !/^\d{10,}$/.test(phone.replace(/[^0-9]/g, ''))) {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: `❌ Invalid phone number\n\nPlease include country code (e.g., +1234567890)`
    };
    msg.topic = 'send';
    return msg;
}

// Create MQTT command payload
const timestamp = new Date().toISOString();
const requestId = `telegram-sms-${Date.now()}`;

// Store original telegram data
const telegramData = msg.telegram;

// Create MQTT message
msg.payload = {
    to: phone,
    text: message
};

msg.topic = 'sms/gateway/command/send';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

// Create confirmation message for Telegram
const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `📱 Sending SMS...\n\nTo: ${phone}\nMessage: ${message.substring(0, 50)}${message.length > 50 ? '...' : ''}\n\nRequest ID: ${requestId}`
    },
    topic: 'send'
};

// Send both MQTT command and Telegram confirmation
return [msg, confirmationMsg];

// Get latest status from flow context
const status = flow.get('status_metadata_sms_gateway') || {
    currentState: 'Unknown',
    lastReportedMs: null
};

const statusData = flow.get('sms_gateway_status') || {};

let statusText = '📱 *SMS Gateway Status*\n\n';

// Connection status
const wifi = statusData.wifi || 'unknown';
const mqtt = statusData.mqtt || 'unknown';
const gsm = statusData.gsm || 'unknown';

const wifiEmoji = wifi === 'connected' ? '🟢' : '🔴';
const mqttEmoji = mqtt === 'connected' ? '🟢' : '🔴';
const gsmEmoji = gsm === 'initialized' ? '🟢' : '🔴';

statusText += `${wifiEmoji} WiFi: ${wifi}\n`;
statusText += `${mqttEmoji} MQTT: ${mqtt}\n`;
statusText += `${gsmEmoji} GSM: ${gsm}\n\n`;

// Last update
if (status.lastReportedMs) {
    const lastUpdate = new Date(status.lastReportedMs);
    const diffMs = Date.now() - status.lastReportedMs;
    const diffSec = Math.floor(diffMs / 1000);

    if (diffSec < 60) {
        statusText += `Last update: ${diffSec}s ago`;
    } else if (diffSec < 3600) {
        statusText += `Last update: ${Math.floor(diffSec / 60)}m ago`;
    } else {
        statusText += `Last update: ${lastUpdate.toLocaleString()}`;
    }
} else {
    statusText += 'Last update: Never';
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

// Get message log from flow context
const messageLog = flow.get('sms_message_log') || [];

if (messageLog.length === 0) {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: '📭 No SMS messages received yet.'
    };
    msg.topic = 'send';
    return msg;
}

// Get last 5 messages
const recentMessages = messageLog.slice(0, 5);

let logText = `📱 *Recent SMS Messages* (${messageLog.length} total)\n\n`;

recentMessages.forEach((sms, index) => {
    const date = new Date(sms.timestamp);
    const timeStr = date.toLocaleString();

    logText += `${index + 1}. *From:* ${sms.from}\n`;
    logText += `   *Time:* ${timeStr}\n`;
    logText += `   *Message:* ${sms.text.substring(0, 100)}${sms.text.length > 100 ? '...' : ''}\n\n`;
});

if (messageLog.length > 5) {
    logText += `_... and ${messageLog.length - 5} more messages_`;
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: logText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

// Only notify for telegram-initiated commands
const requestId = msg.telegram?.requestId || '';
if (!requestId.startsWith('telegram-')) {
    return null; // Not a telegram command
}

const chatIds = flow.get('telegram_chat_ids') || [];
if (chatIds.length === 0) {
    return null;
}

// Format response message
const response = msg.payload;
const success = response.success || false;
const phone = response.to || 'Unknown';
const timestamp = response.timestamp || new Date().toISOString();

const statusEmoji = success ? '✅' : '❌';
const status = success ? 'Success' : 'Failed';

let responseText = `${statusEmoji} *SMS ${status}*\n\n`;
responseText += `To: ${phone}\n`;
responseText += `Time: ${new Date(timestamp).toLocaleString()}\n`;

if (requestId) {
    responseText += `\nRequest ID: \`${requestId}\``;
}

// Send to all registered chats (Node-RED will send each as separate message)
return chatIds.map(chatId => ({
    payload: {
        chatId: chatId,
        type: 'message',
        content: responseText,
        parse_mode: 'Markdown'
    }
}));

// Get message text from flow context (set by 511 flow)
const messageLog = flow.get('sms_message_log') || [];
const latestMessage = messageLog[0];

if (!latestMessage) {
    return null;
}

const chatIds = flow.get('telegram_chat_ids') || [];
if (chatIds.length === 0) {
    return null;
}

// Format notification
const notificationText = `📱 *New SMS Received*\n\n` +
    `From: ${latestMessage.from}\n` +
    `Message: ${latestMessage.text.substring(0, 200)}${latestMessage.text.length > 200 ? '...' : ''}\n` +
    `Time: ${new Date(latestMessage.timestamp).toLocaleString()}`;

// Send to all registered chats
return chatIds.map(chatId => ({
    payload: {
        chatId: chatId,
        type: 'message',
        content: notificationText,
        parse_mode: 'Markdown'
    }
}));
